service.method:

SELECT
	DEPT
FROM
	SDEPT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${COMPANY_CODE}	
	AND DEPT 			= ${DEPT}


UPDATE SDEPT
	SET
		  DEPT_NAME_LOC	  = ${DEPT_NAME_LOC}
		, PARENT_DEPT	  = ${PARENT_DEPT}
		, DEL_FLAG		  = ${DEL_FLAG}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}
		, MANAGER_ID 	  = ${MANAGER_ID}
WHERE
			HOUSE_CODE    = ${session.HOUSE_CODE}
		AND COMPANY_CODE  = ${COMPANY_CODE}
		AND DEPT		  = ${DEPT}


UPDATE BAT_UP_IMDEPT
	SET
		 IF_FLAG	  = ${IF_RESULT}
WHERE
			COMPANY  	= ${COMPANY_CODE}
		AND DEPT_CD		= ${DEPT}
		AND INS_TIME    = ${INS_TIME}


UPDATE SDEPT
SET
	DEL_FLAG = ${DEL_FLAG}
WHERE
		COMPANY_CODE  = ${COMPANY_CODE}
	AND DEPT		  = ${DEPT}


INSERT INTO SDEPT
	(
		  HOUSE_CODE
		, COMPANY_CODE
		, DEPT
		, DEPT_NAME_LOC
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID				
		, PARENT_DEPT
		, DEL_FLAG
		, MANAGER_ID
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${COMPANY_CODE}
		, ${DEPT}
		, ${DEPT_NAME_LOC}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, ${PARENT_DEPT}
		, ${DEL_FLAG}
		, ${MANAGER_ID}
	)
